const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const dir = path.join(root, 'assets/rogue-art4');
const art = {};
for (const filename of fs.readdirSync(dir).sort()) {
  if (!filename.endsWith('.webp')) continue;
  art[path.basename(filename, '.webp')] = 'data:image/webp;base64,' + fs.readFileSync(path.join(dir, filename)).toString('base64');
}
fs.writeFileSync(path.join(root, 'src/rogue-art-data.js'),
  '/* Generated by node dev/pack-rogue-art.cjs. */\nconst ROGUE_ART_DATA = ' + JSON.stringify(art, null, 2) + ';\n');
